This is the simplest case: $C = A + B$.

### 1. Original CUDA Code

```c++
// cuda_vector_add.cu
#include <cuda_runtime.h>
#include <stdio.h>

// CUDA Kernel
__global__ void vectorAddKernel(const float* A, const float* B, float* C, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        C[i] = A[i] + B[i];
    }
}

void run_cuda_vector_add(float* h_A, float* h_B, float* h_C, int N) {
    // 1. Allocate device memory
    float *d_A, *d_B, *d_C;
    cudaMalloc((void**)&d_A, N * sizeof(float));
    cudaMalloc((void**)&d_B, N * sizeof(float));
    cudaMalloc((void**)&d_C, N * sizeof(float));

    // 2. Copy host to device
    cudaMemcpy(d_A, h_A, N * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, N * sizeof(float), cudaMemcpyHostToDevice);

    // 3. Kernel Launch Configuration
    int threadsPerBlock = 256;
    int blocksPerGrid = (N + threadsPerBlock - 1) / threadsPerBlock;

    // 4. Launch Kernel
    vectorAddKernel<<<blocksPerGrid, threadsPerBlock>>>(d_A, d_B, d_C, N);

    // 5. Copy device to host
    cudaMemcpy(h_C, d_C, N * sizeof(float), cudaMemcpyDeviceToHost);

    // 6. Cleanup
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
}
```

### 2. RAJA Conversion

We replace the explicit memory management and kernel launch with RAJA's `raja::parallel_for` and RAJA's memory handling.

```c++
// raja_vector_add.cpp
#include <iostream>
#include <vector>
#include <raja/raja.hpp>

// Define the RAJA execution policy (we choose CUDA as the backend)
using namespace raja;

void run_raja_vector_add(std::vector<float>& h_A, std::vector<float>& h_B, std::vector<float>& h_C, int N) {
    // 1. Define the execution policy (Targeting CUDA)
    // This tells RAJA to use the CUDA backend for execution.
    auto policy = make_policy<cuda_policy>();

    // 2. RAJA handles memory allocation and transfer implicitly 
    // when using RAJA's memory views/buffers, but for simplicity here, 
    // we use RAJA's parallel_for which manages the execution context.

    // 3. The parallel loop replaces the kernel launch.
    // RAJA automatically maps the loop iterations to threads/blocks 
    // according to the chosen policy (CUDA).
    parallel_for(
        range(0, N), // The iteration space (0 to N-1)
        policy,
        [&](int i) {
            // This lambda function runs on a thread assigned by RAJA
            h_C[i] = h_A[i] + h_B[i];
        }
    );

    // Note: In a full RAJA application, you would use raja::buffer 
    // to manage device memory explicitly, but for simple host-side 
    // operations accelerated by RAJA, this structure is sufficient.
}

int main() {
    const int N = 1024 * 1024;
    std::vector<float> A(N, 1.0f);
    std::vector<float> B(N, 2.0f);
    std::vector<float> C(N);

    std::cout << "--- Running RAJA Vector Addition (Targeting CUDA) ---\n";

    // RAJA handles the dispatch to the CUDA backend here
    run_raja_vector_add(A, B, C, N);

    std::cout << "First element of C: " << C[0] << " (Expected: 3.0)\n";
    std::cout << "Last element of C: " << C[N-1] << " (Expected: 3.0)\n";

    return 0;
}
```

