## 1. Vector Addition

### CUDA version

```cpp
// vecadd.cu
#include <cuda_runtime.h>
#include <iostream>

__global__ void vecadd(const float *a, const float *b, float *c, int N)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) c[i] = a[i] + b[i];
}

int main()
{
    const int N = 1<<20;          // 1M elements
    size_t sz = N*sizeof(float);

    float *h_a = new float[N];
    float *h_b = new float[N];
    float *h_c = new float[N];

    for (int i=0;i<N;i++) { h_a[i] = i; h_b[i] = 2*i; }

    float *d_a, *d_b, *d_c;
    cudaMalloc(&d_a, sz); cudaMalloc(&d_b, sz); cudaMalloc(&d_c, sz);
    cudaMemcpy(d_a, h_a, sz, cudaMemcpyHostToDevice);
    cudaMemcpy(d_b, h_b, sz, cudaMemcpyHostToDevice);

    int threads = 256;
    int blocks   = (N + threads - 1)/threads;
    vecadd<<<blocks,threads>>>(d_a, d_b, d_c, N);
    cudaDeviceSynchronize();

    cudaMemcpy(h_c, d_c, sz, cudaMemcpyDeviceToHost);

    std::cout << "c[0]=" << h_c[0] << "  c[N-1]=" << h_c[N-1] << "\n";

    cudaFree(d_a); cudaFree(d_b); cudaFree(d_c);
    delete[] h_a; delete[] h_b; delete[] h_c;
}
```

### RAJA version

```cpp
// vecadd_raja.cu
#include <RAJA/RAJA.hpp>
#include <iostream>
#include <vector>

int main()
{
    constexpr int N = 1<<20;          // 1M elements
    std::vector<float> h_a(N), h_b(N), h_c(N);

    for (int i=0;i<N;i++) { h_a[i] = i; h_b[i] = 2*i; }

    // RAJA::cuda_exec<threads> will launch a 1‑D grid of blocks
    constexpr int threads = 256;
    RAJA::forall<RAJA::cuda_exec<threads>>(
        RAJA::RangeSegment(0,N),
        [&](int i){ h_c[i] = h_a[i] + h_b[i]; });

    std::cout << "c[0]=" << h_c[0] << "  c[N-1]=" << h_c[N-1] << "\n";
}
```

**Build & run**

```bash
nvcc -std=c++17 -O3 -I/path/to/raja/include vecadd_raja.cu -o vecadd_raja
./vecadd_raja
```

The RAJA code is *identical* in logic to the CUDA kernel, but the launch parameters are hidden inside the `RAJA::cuda_exec<threads>` policy.  
If you want to use a different launch configuration, just change the template argument or pass a `RAJA::cuda_exec<threads, blocks>` policy.

