## 2. 2‑D 5‑point Stencil (Heat Equation)

### CUDA version

```cpp
// stencil.cu
#include <cuda_runtime.h>
#include <iostream>

__global__ void stencil(const float *in, float *out, int nx, int ny)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;   // x‑index
    int j = blockIdx.y * blockDim.y + threadIdx.y;   // y‑index

    if (i>0 && i<nx-1 && j>0 && j<ny-1) {
        int idx = j*nx + i;
        out[idx] = 0.25f * ( in[idx-1] + in[idx+1]
                           + in[idx-nx] + in[idx+nx] );
    }
}

int main()
{
    const int nx = 512, ny = 512;
    size_t sz = nx*ny*sizeof(float);

    float *h_in  = new float[nx*ny];
    float *h_out = new float[nx*ny];
    for (int j=0;j<ny;j++)
      for (int i=0;i<nx;i++)
        h_in[j*nx+i] = (i+j) * 0.01f;

    float *d_in, *d_out;
    cudaMalloc(&d_in, sz); cudaMalloc(&d_out, sz);
    cudaMemcpy(d_in, h_in, sz, cudaMemcpyHostToDevice);

    dim3 threads(16,16);
    dim3 blocks((nx+threads.x-1)/threads.x,
                (ny+threads.y-1)/threads.y);
    stencil<<<blocks,threads>>>(d_in, d_out, nx, ny);
    cudaDeviceSynchronize();

    cudaMemcpy(h_out, d_out, sz, cudaMemcpyDeviceToHost);
    std::cout << "out[0]=" << h_out[0] << "  out[nx*ny-1]=" << h_out[nx*ny-1] << "\n";

    cudaFree(d_in); cudaFree(d_out);
    delete[] h_in; delete[] h_out;
}
```

### RAJA version

```cpp
// stencil_raja.cu
#include <RAJA/RAJA.hpp>
#include <iostream>
#include <vector>

int main()
{
    constexpr int nx = 512, ny = 512;
    std::vector<float> h_in(nx*ny), h_out(nx*ny);

    for (int j=0;j<ny;j++)
      for (int i=0;i<nx;i++)
        h_in[j*nx+i] = (i+j) * 0.01f;

    // 2‑D index set: (j, i)
    RAJA::IndexSet2D indexSet(ny, nx);

    // RAJA::kernel with a 2‑D range segment
    RAJA::kernel<RAJA::cuda_exec<16,16>>(
        RAJA::make_tuple(RAJA::RangeSegment(0,ny), RAJA::RangeSegment(0,nx)),
        [=] RAJA_HOST_DEVICE (int j, int i)
        {
            if (i>0 && i<nx-1 && j>0 && j<ny-1) {
                int idx = j*nx + i;
                h_out[idx] = 0.25f * ( h_in[idx-1] + h_in[idx+1]
                                     + h_in[idx-nx] + h_in[idx+nx] );
            }
        });

    std::cout << "out[0]=" << h_out[0] << "  out[nx*ny-1]=" << h_out[nx*ny-1] << "\n";
}
```

**Explanation**

* `RAJA::cuda_exec<16,16>` tells RAJA to launch a 2‑D grid with 16×16 threads per block (matching the CUDA launch).
* `RAJA::make_tuple(RAJA::RangeSegment(0,ny), RAJA::RangeSegment(0,nx))` defines the 2‑D iteration space.
* The lambda is marked `RAJA_HOST_DEVICE` so it can be compiled for both host and device; RAJA will automatically generate the device code.

**Build & run**

```bash
nvcc -std=c++17 -O3 -I/path/to/raja/include stencil_raja.cu -o stencil_raja
./stencil_raja
```

