    RAJA::forall<RAJA::cuda_exec<256, 256>>(RAJA::RangeSegment(0, M), RAJA::RangeSegment(0, N), [=] RAJA_HOST_DEVICE(int idx, int idy) {
        float sum = 0.0f;
        for (int k = 0; k < P; k++) {
            sum += A[idx * P + k] * B[k * N + idy];
        }
        C[idx * N + idy] = sum;
    });

    // Synchronize
    cudaDeviceSynchronize();

    // Print result
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
