Converting CUDA code to RAJA (Range-based Abstraction for Parallelism and Algorithms) can be a bit involved, but it's a great way to make your code more portable and maintainable. RAJA is designed to work across multiple parallel backends, including CUDA, OpenMP, and HIP.

Below are two examples of converting a simple CUDA kernel to RAJA. The first example is a simple vector addition, and the second is a more complex matrix multiplication.

### Example 1: Vector Addition

#### CUDA Code
```cuda
__global__ void vectorAdd(float *a, float *b, float *c, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < N) {
        c[i] = a[i] + b[i];
    }
}
```

#### RAJA Code
```cpp
#include <RAJA/RAJA.hpp>
#include <iostream>

int main() {
    int N = 1024;
    int threadsPerBlock = 256;
    int blocksPerGrid = (N + threadsPerBlock - 1) / threadsPerBlock;

    // Allocate and initialize data
    float *a, *b, *c;
    cudaMalloc(&a, N * sizeof(float));
    cudaMalloc(&b, N * sizeof(float));
    cudaMalloc(&c, N * sizeof(float));

    // Initialize arrays
    for (int i = 0; i < N; ++i) {
        a[i] = 1.0f;
        b[i] = 2.0f;
    }

    // RAJA kernel
    RAJA::KernelPolicy<RAJA::seq_exec> seq_policy;
    RAJA::KernelPolicy<RAJA::cuda_exec, RAJA::cuda_stream_exec> cuda_policy;

    RAJA::forall<RAJA::cuda_exec>(RAJA::RangeSegment(0, N), RAJA::LambdaSegment([a, b, c](int i) {
        c[i] = a[i] + b[i];
    }));

    // Copy results back to host
    cudaMemcpy(c, a, N * sizeof(float), cudaMemcpyDeviceToHost);

    // Print results
    for (int i = 0; i < 10; ++i) {
        std::cout << c[i] << " ";
    }
    std::cout << std::endl;

    // Free memory
    cudaFree(a);
    cudaFree(b);
    cudaFree(c);

    return 0;
}
```

### Example 2: Matrix Multiplication

#### CUDA Code
```cuda
__global__ void matMul(float *A, float *B, float *C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    float sum = 0.0f;
    if (row < N && col < N) {
        for (int k = 0; k < N; ++k) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}
```

