    RAJA::forall<RAJA::cuda_exec>(RAJA::RangeSegment(0, N), RAJA::RangeSegment(0, N), RAJA::LambdaSegment([A, B, C, N](int row, int col) {
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
